<script setup lang="ts">
import {ref,reactive,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import {api} from '../api'
import type {PageResult,PaperSummary} from '../types/research'
import {useResource} from '../composables/useResource'
import AsyncState from '../components/AsyncState.vue'
import Icon from '../components/Icon.vue'
const router=useRouter(),selected=ref<PaperSummary[]>([]),filters=reactive({q:'',year:undefined as number|undefined,has_fulltext:'' as boolean|'',has_analysis:'' as boolean|'',page:1,page_size:Number(localStorage.getItem('rp-page-size'))||20})
const {data,loading,error,load}=useResource<PageResult<PaperSummary>>({items:[],total:0,page:1,page_size:Number(localStorage.getItem('rp-page-size'))||20})
function refresh(reset=false){if(reset)filters.page=1;load(()=>api.papers({...filters}))}
onMounted(()=>refresh())
</script>
<template><div class="page-heading"><div><div class="eyebrow">YOUR KNOWLEDGE COLLECTION</div><h1>我的文献库 <span class="heading-count">{{data.total}}</span></h1><p>收藏、阅读和关联证据，让文献成为你的研究积累。</p></div><RouterLink class="primary-link" to="/search"><Icon name="Plus"/>添加文献</RouterLink></div><form class="panel library-filters" @submit.prevent="refresh(true)"><el-input v-model="filters.q" placeholder="搜索标题或 DOI" clearable aria-label="搜索文献"/><el-input-number v-model="filters.year" :controls="false" placeholder="发表年份" :min="1900" :max="2100" aria-label="发表年份"/><el-select v-model="filters.has_fulltext" placeholder="全文状态" aria-label="全文状态"><el-option label="全部全文状态" value=""/><el-option label="已获取全文" :value="true"/><el-option label="尚无全文" :value="false"/></el-select><el-select v-model="filters.has_analysis" placeholder="分析状态" aria-label="分析状态"><el-option label="全部分析状态" value=""/><el-option label="已分析" :value="true"/><el-option label="未分析" :value="false"/></el-select><el-button native-type="submit">筛选</el-button><el-button @click="refresh()" aria-label="刷新文献列表"><Icon name="Refresh"/></el-button></form><div class="result-toolbar"><span class="muted">{{selected.length?`已选择 ${selected.length} 篇`:'所有已收藏文献'}}</span><el-button :disabled="selected.length<2||selected.length>5||selected.some(p=>!p.has_analysis)" @click="router.push({path:'/reviews',query:{paperIds:selected.map(p=>p.id).join(',')}})">用于文献综述 →</el-button></div><AsyncState :loading="loading" :error="error" :empty="!data.items.length" title="还没有匹配的文献" @retry="refresh()"><template #action><RouterLink class="primary-link" to="/search">去检索论文 →</RouterLink></template><div class="panel table-panel"><el-table :data="data.items" @selection-change="selected=$event" row-key="id"><el-table-column type="selection" width="46"/><el-table-column label="论文" min-width="330"><template #default="{row}"><div class="table-paper"><code class="muted">P{{row.id}}</code><RouterLink :to="`/papers/${row.id}`" class="paper-title">{{row.title}}</RouterLink><small>{{row.authors.slice(0,3).join(' · ')||'作者未记录'}} · {{row.year||'年份未知'}}</small><code>{{row.doi||'DOI 未记录'}}</code></div></template></el-table-column><el-table-column label="全文" width="130"><template #default="{row}"><span class="status-chip" :class="row.has_fulltext?'success':'neutral'"><i/>{{row.has_fulltext?'已获取全文':'尚无全文'}}</span></template></el-table-column><el-table-column label="分析" width="115"><template #default="{row}"><span class="status-chip" :class="row.has_analysis?'blue':'neutral'"><i/>{{row.has_analysis?'已分析':'未分析'}}</span></template></el-table-column><el-table-column label="操作" width="160"><template #default="{row}"><RouterLink :to="`/papers/${row.id}`">详情</RouterLink><span class="action-divider">/</span><RouterLink v-if="row.has_fulltext" :to="`/analysis?paperId=${row.id}`">分析 ↗</RouterLink><RouterLink v-else :to="`/papers/${row.id}?tab=pdf`">上传全文</RouterLink></template></el-table-column></el-table></div><el-pagination v-model:current-page="filters.page" :page-size="filters.page_size" :total="data.total" layout="total,prev,pager,next" @current-change="refresh()"/></AsyncState><p class="note page-note">收藏、全文和分析状态分别记录。已收藏的论文不会自动下载全文。</p></template>
